/// Query parameters for `GET /externalposts`.
#[derive(Debug, Clone, Default)]
pub struct GetExternalpostsQuery {
    /// If set, only posts created before this date are returned. The date must be in RFC3339 format (Zulu-Date).
    pub before: Option<chrono::DateTime<chrono::Utc>>,
    /// If set, posts created at the "before" date are included in the result, if the guids of the posts are lexically smaller than the last_post_indentifier. Will be ignored if "before" is not set.
    pub last_post_indentifier: Option<String>,
    /// If set, only posts created after this date are returned. The date must be in RFC3339 format (Zulu-Date).
    pub after: Option<chrono::DateTime<chrono::Utc>>,
    /// If set posts of these groups are returned.
    pub external_group_guid: Option<Vec<String>>,
    /// If set posts of these instances are returned.
    pub external_instance_guid: Option<Vec<String>>,
    /// If set, the response will include the specified data.
    /// Allowed values: `linkings`.
    pub include: Option<Vec<String>>,
    /// Number of results per page.
    pub limit: Option<i64>,
}

impl GetExternalpostsQuery {
    pub(crate) fn to_query(&self) -> Query {
        let mut q = Query::new();
        self.before.push_query("before", &mut q);
        self.last_post_indentifier.push_query("last_post_indentifier", &mut q);
        self.after.push_query("after", &mut q);
        self.external_group_guid.push_query("external_group_guid[]", &mut q);
        self.external_instance_guid.push_query("external_instance_guid[]", &mut q);
        self.include.push_query("include[]", &mut q);
        self.limit.push_query("limit", &mut q);
        q
    }
}

